import json
from pathlib import Path

DATA = Path('projects/todos.json')

def load():
    if DATA.exists():
        return json.loads(DATA.read_text(encoding='utf-8'))
    return []

def save(items):
    DATA.write_text(json.dumps(items, ensure_ascii=False, indent=2), encoding='utf-8')

def add(item):
    items = load()
    items.append({'task': item, 'done': False})
    save(items)

def complete(index):
    items = load()
    items[index]['done'] = True
    save(items)

def show():
    for i, t in enumerate(load()):
        mark = '[x]' if t['done'] else '[ ]'
        print(i, mark, t['task'])

if __name__ == '__main__':
    add('미니프로젝트 마무리')
    add('README 정리')
    complete(0)
    show()

