import json
from pathlib import Path

DATA = Path('projects/contacts.json')

def load():
    if DATA.exists():
        return json.loads(DATA.read_text(encoding='utf-8'))
    return []

def save(contacts):
    DATA.write_text(json.dumps(contacts, ensure_ascii=False, indent=2), encoding='utf-8')

def add_contact(name, phone):
    contacts = load()
    for c in contacts:
        if c['name'] == name:
            print('이미 있음, 번호 업데이트')
            c['phone'] = phone
            save(contacts)
            return
    contacts.append({'name': name, 'phone': phone})
    save(contacts)

def find_contact(name):
    for c in load():
        if name in c['name']:
            return c
    return None

def list_contacts():
    contacts = load()
    if not contacts:
        print('연락처 없음')
        return
    for c in contacts:
        print(f"{c['name']}: {c['phone']}")

if __name__ == '__main__':
    add_contact('민수', '010-1111-2222')
    add_contact('지영', '010-3333-4444')
    list_contacts()
    print('검색:', find_contact('민'))

